import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine(); // Consume newline
        TaskManager manager = new TaskManager();
        for (int i = 0; i < n; i++) {
            String command = sc.nextLine();
            manager.processCommand(command);
        }
        sc.close();
    }
