import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        NameManager manager = new NameManager();
        int n = sc.nextInt();
        sc.nextLine();
        for (int i = 0; i < n; i++) {
            manager.addName(sc.nextLine());
        }
        int index = sc.nextInt();
        manager.printNameAtIndex(index);
        sc.close();
    }
}

